-- ===========================================================================
-- Aerodromos da Regiao Norte (ANAC) - Script de carga
-- PostgreSQL
--
-- Fonte: anac_aerodromos_norte.csv (809 aerodromos, 34 colunas)
-- Gerado a partir do CSV; nenhuma informacao da planilha foi descartada.
--
-- Equipe:
--   - Pedro Andrade Gonçalves de Souza
--   - Julia Labad Jatene
--   - Luan Piedade de Oliveira
--   - Jõao Paulo Oliveira Rodrigues
--
-- Pre-requisito: executar trabalho_aerodromo.sql (o DDL) antes deste script.
--
-- Os identificadores das tabelas com SERIAL sao gravados explicitamente
-- para que as chaves estrangeiras possam referencia-los; as sequencias sao
-- reposicionadas com setval no final do script.
-- ===========================================================================

BEGIN;

-- -------------------------------------------------------------------------
-- estado (7 linhas) - origem: colunas uf e uf_servido
-- -------------------------------------------------------------------------

-- -------------------------------------------------------------------------
-- municipio (242 linhas) - origem: municipio/uf e municipio_servido/uf_servido
-- -------------------------------------------------------------------------

-- -------------------------------------------------------------------------
-- superficie_pista (9 linhas) - origem: pista1_superficie
-- -------------------------------------------------------------------------

-- -------------------------------------------------------------------------
-- tipo_operacao (3 linhas) - origem: operacao_diurna e operacao_noturna
-- -------------------------------------------------------------------------

-- -------------------------------------------------------------------------
-- perfil_operacional (3 linhas) - origem: perfil_operacional_rbac153
-- -------------------------------------------------------------------------

-- -------------------------------------------------------------------------
-- categoria_operacao (3 linhas) - origem: operacao_internacional
-- -------------------------------------------------------------------------

-- -------------------------------------------------------------------------
-- restricao (9 linhas) - origem: restricao
-- -------------------------------------------------------------------------

-- -------------------------------------------------------------------------
-- aerodromo (809 linhas) - entidade central
-- -------------------------------------------------------------------------




-- -------------------------------------------------------------------------
-- pista (653 linhas) - origem: colunas pista1_*
-- -------------------------------------------------------------------------



-- -------------------------------------------------------------------------
-- aerodromo_operacao (1163 linhas) - celulas multivaloradas decompostas
-- -------------------------------------------------------------------------





-- -------------------------------------------------------------------------
-- aerodromo_rbac (71 linhas) - classificacao regulatoria
-- -------------------------------------------------------------------------

-- -------------------------------------------------------------------------
-- aerodromo_categoria_operacao (13 linhas) - celula multivalorada decomposta
-- -------------------------------------------------------------------------

-- -------------------------------------------------------------------------
-- aerodromo_restricao (19 linhas) - origem: restricao
-- -------------------------------------------------------------------------

-- -------------------------------------------------------------------------
-- Reposiciona as sequencias SERIAL apos a carga com ids explicitos
-- -------------------------------------------------------------------------
SELECT setval('municipio_id_municipio_seq', 242);
SELECT setval('superficie_pista_id_superficie_seq', 9);
SELECT setval('tipo_operacao_id_tipo_operacao_seq', 3);
SELECT setval('perfil_operacional_id_perfil_seq', 3);
SELECT setval('categoria_operacao_id_categoria_seq', 3);
SELECT setval('restricao_id_restricao_seq', 9);

COMMIT;

-- -------------------------------------------------------------------------
-- Conferencia: o resultado esperado esta na coluna 'esperado'
-- -------------------------------------------------------------------------
SELECT tabela, esperado, carregado,
       CASE WHEN esperado = carregado THEN 'OK' ELSE 'DIVERGENTE' END AS conferencia
FROM (
    SELECT 'estado'                           AS tabela,     7 AS esperado, (SELECT count(*) FROM estado) AS carregado UNION ALL
    SELECT 'municipio'                        AS tabela,   242 AS esperado, (SELECT count(*) FROM municipio) AS carregado UNION ALL
    SELECT 'superficie_pista'                 AS tabela,     9 AS esperado, (SELECT count(*) FROM superficie_pista) AS carregado UNION ALL
    SELECT 'tipo_operacao'                    AS tabela,     3 AS esperado, (SELECT count(*) FROM tipo_operacao) AS carregado UNION ALL
    SELECT 'perfil_operacional'               AS tabela,     3 AS esperado, (SELECT count(*) FROM perfil_operacional) AS carregado UNION ALL
    SELECT 'categoria_operacao'               AS tabela,     3 AS esperado, (SELECT count(*) FROM categoria_operacao) AS carregado UNION ALL
    SELECT 'restricao'                        AS tabela,     9 AS esperado, (SELECT count(*) FROM restricao) AS carregado UNION ALL
    SELECT 'aerodromo'                        AS tabela,   809 AS esperado, (SELECT count(*) FROM aerodromo) AS carregado UNION ALL
    SELECT 'pista'                            AS tabela,   653 AS esperado, (SELECT count(*) FROM pista) AS carregado UNION ALL
    SELECT 'aerodromo_operacao'               AS tabela,  1163 AS esperado, (SELECT count(*) FROM aerodromo_operacao) AS carregado UNION ALL
    SELECT 'aerodromo_rbac'                   AS tabela,    71 AS esperado, (SELECT count(*) FROM aerodromo_rbac) AS carregado UNION ALL
    SELECT 'aerodromo_categoria_operacao'     AS tabela,    13 AS esperado, (SELECT count(*) FROM aerodromo_categoria_operacao) AS carregado UNION ALL
    SELECT 'aerodromo_restricao'              AS tabela,    19 AS esperado, (SELECT count(*) FROM aerodromo_restricao) AS carregado
) AS c ORDER BY tabela;
